{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Isotretinoin, the closest retinoid scaffold analogue, has a systemic bioavailability of 40% at 1 mg/kg/day, directly supporting F>=20% for the query's retinoid-like structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Lidose-isotretinoin does not require a high-fat meal for maximum bioavailability, showing that lipophilic retinoids can be formulated to achieve adequate oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lycopene, a highly lipophilic polyene, showed 24.5% bioavailability in humans, just above the 20% threshold, supporting that very lipophilic molecules in this class can meet the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Teriflunomide, a lipophilic amide, has absolute oral bioavailability approaching 100%, supporting high F for amide-containing lipophilic drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F>=20%) because the closest retinoid analogue isotretinoin has ~40% bioavailability, lycopene (a similarly lipophilic polyene) reaches ~24.5%, and lipophilic amides such as teriflunomide approach 100%; no evidence supports F<20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact retinoyl-4-aminophenol conjugate.",
    "No IV formulation data for the query or exact analogue.",
    "First-pass metabolism (phenol glucuronidation/sulfation) and amide stability are unknown.",
    "Solubility and dissolution are not experimentally measured; high logP may limit absorption without formulation.",
    "Food effect and formulation (e.g., lipid-based) are not specified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

